  // --- Admin batch 1: Compliance, Activations, New Connection Wizard, Usage, Digest, Waitlist ---
  "admin.compliance.title": "合规状态",
  "admin.compliance.subtitle": "如实说明 Curf 今天做了什么、即将推出什么，以及尚未做到的部分。可作为安全问卷调查的标准答案。",
  "admin.compliance.section.today": "我们今天已经做到的",
  "admin.compliance.section.inProgress": "正在进行中（未来 90 天）",
  "admin.compliance.section.gaps": "我们尚未做到的 — 对审核方坦诚相告",
  "admin.compliance.section.surface": "涉及范围",
  "admin.compliance.item.tenantIsolation.title": "每一层都做租户隔离",
  "admin.compliance.item.tenantIsolation.body": "每个 API 都通过 requireUser + tenantWhere 强制执行 tenantId 过滤。Prisma 行数据泄露只有在每个多租户模型的代码审查都失效时才可能发生 — 审计日志会记录任何跨租户探测行为。",
  "admin.compliance.item.secretsEncryption.title": "静态密钥加密",
  "admin.compliance.item.secretsEncryption.body": "API 密钥、SaaS 连接器令牌（Stripe / HubSpot / Slack bot token）以及每租户的 LLM 提供商密钥，在存储前都会通过 lib/secrets.ts 以 AES-256-GCM 加密。明文绝不落盘。",
  "admin.compliance.item.webhookHmac.title": "对入站 Webhook 进行 HMAC 签名验证",
  "admin.compliance.item.webhookHmac.body": "Slack /events 与交互事件、Lake 数据接入令牌、以及嵌入令牌，全部使用恒定时间比较验证 HMAC 签名。Slack 的重放窗口为 5 分钟。",
  "admin.compliance.item.auditLog.title": "只增不改的审计日志",
  "admin.compliance.item.auditLog.body": "每一个与安全相关的操作（登录、角色变更、创建数据源、生成分享令牌、修改 Lake 架构、发布公开应用）都会在 AuditEvent 模型中写入一行记录，应用内永不修改、永不删除。",
  "admin.compliance.item.lakeBackups.title": "每日 Lake 备份 + 时间点恢复",
  "admin.compliance.item.lakeBackups.body": "Lake 表每晚都会被快照为压缩的本地文件。Free 版保留 30 天 / Team 版 90 天 / Business 版 365 天。手动快照无论所在套餐均至少保留 365 天。恢复前会先创建一份安全快照，因此一次失败的恢复也可以撤销。",
  "admin.compliance.item.lakeRls.title": "Lake 表的行级访问控制",
  "admin.compliance.item.lakeRls.body": "每张 Lake 表都可以设为全租户可见、限定特定角色，或仅所有者可见（私有）。隐藏的表甚至不会出现在目录列表中 — 与'未找到'返回相同的状态码，从而隐藏其存在。",
  "admin.compliance.item.schemaMigrations.title": "带审计轨迹的架构迁移",
  "admin.compliance.item.schemaMigrations.body": "在 Lake 表上新增 / 重命名 / 删除列都会触发专属的审计事件。运行器会立即刷新缓存的 schemaJson，避免报表渲染器使用过期的结构。",
  "admin.compliance.item.noThirdPartyAi.title": "AI 运行在 Curf AI 上，或您自己的密钥上",
  "admin.compliance.item.noThirdPartyAi.body": "Ask Curf、Auto-Curf、监控建议以及图表说明层运行在 Curf AI 上——由 Curf 签约的模型提供方，列于公开的分包处理方页面——除非本工作区在 Tenant Settings → LLM 连接了自己的提供方，此时请求依据您与该提供方的协议进行，不经过 Curf 的提供方。自托管实例可通过 CURF_LLM=off 完全关闭 AI 路径；启发式回退仍能给出可用结果。",
  "admin.compliance.item.exportDeletion.title": "一键数据导出与删除",
  "admin.compliance.item.exportDeletion.body": "租户管理员可以申请全租户范围的 CSV/Parquet 导出（Phase 2 功能，进行中），并可永久删除任意 Lake 表。GDPR 数据主体请求（DSR）流程即基于这些能力构建。",
  "admin.compliance.item.pdpaRecord.title": "PDPA 数据处理记录",
  "admin.compliance.item.pdpaRecord.body": "租户管理员可以在 Admin -> Tenant 中声明一份处理记录摘要——数据类别、处理目的、法律依据、保留期限。这是每个租户一份的汇总记录，而非完整的多活动登记册。",
  "admin.compliance.item.restReadOnly.title": "只读 REST 连接",
  "admin.compliance.item.restReadOnly.body": "REST 连接可以标记为只读，这会阻止任何非 GET 方法的报表查询请求。SQL 类型的连接（Postgres、MySQL、Snowflake、BigQuery、SQLite）本身已无条件限制为仅 SELECT。",
  "admin.compliance.item.offsiteBackup.title": "异地备份至 S3 / Spaces",
  "admin.compliance.item.offsiteBackup.body": "目前快照与生产数据库位于同一块磁盘。Phase 3 将上线按套餐区分的 S3（或 DigitalOcean Spaces）目标存储，避免磁盘故障连带丢失备份。",
  "admin.compliance.item.piiTagging.title": "列级 PII 标记与脱敏",
  "admin.compliance.item.piiTagging.body": "上传时可将某个 Lake 列标记为 PII / 财务 / 健康数据；无权限角色在查询时会在运行器层看到该列被脱敏。适用于共享仪表板的场景 — 所有者看到完整数据，查看者看到脱敏后的数据。",
  "admin.compliance.item.costTelemetry.title": "按租户统计成本",
  "admin.compliance.item.costTelemetry.body": "存储字节数、查询 CPU 用量、导入数据量、LLM 令牌花费 — 都会展示在 /admin/usage，方便管理员查看（并据此计费）真实消耗。",
  "admin.compliance.item.soc2.title": "正式的 SOC 2 Type II 审计",
  "admin.compliance.item.soc2.body": "我们已经建好了相应的控制措施，但尚未接受第三方审计机构的审计。SOC 2 通常需要 6 个月，最好配合企业合同的节奏来安排。发送邮件至 security@curf.ai 即可开始这项讨论。",
  "admin.compliance.item.hipaa.title": "HIPAA 业务伙伴协议（BAA）",
  "admin.compliance.item.hipaa.body": "目前尚无 BAA。医疗类工作负载应等待数据层路线图 Phase 3（客户自管密钥的列级加密、数据驻留选择）。详见 ROADMAP-DATA-LAYER.md。",
  "admin.compliance.item.residency.title": "多区域数据驻留",
  "admin.compliance.item.residency.body": "目前每套 Curf 部署只支持单一区域。EU / APAC / US 区域固定将在 Phase 3 上线。",
  "admin.compliance.item.ssoCustomIdp.title": "自定义 IdP 的 SSO（Okta / Azure AD）",
  "admin.compliance.item.ssoCustomIdp.body": "内置 SSO 支持 Google + GitHub。自定义 IdP 支持按需求开放 — 很乐意为付费试点项目优先安排。",
  "admin.compliance.surface.intro": "涉及敏感数据的模型：",
  "admin.compliance.surface.connectionStrings": "（连接字符串）",
  "admin.compliance.surface.botTokens": "（bot token）",
  "admin.compliance.surface.outro": "每一个都通过 Prisma {code} 限定租户范围，并配合运行时 ACL。",
  "admin.compliance.surface.roadmapPre": "完整的数据层路线图请见",
  "admin.compliance.surface.roadmapPost": "了解所有进行中的工作。",
  "admin.compliance.questionsIntro": "安全问卷通常不会涉及的问题 — 我们很乐意以书面形式解答：",
  "admin.compliance.q.subprocessors": "具体的分包处理方（Avalant 位于泰国的自有基础设施负责托管、您选择的 LLM 提供商、Stripe 负责计费）",
  "admin.compliance.q.incidentResponse": "事件响应手册 + 数据泄露通知时间线",
  "admin.compliance.q.pentest": "渗透测试节奏（每年一次第三方测试 + 持续的内部审查）",
  "admin.compliance.q.bugBounty": "漏洞赏金范围（筹备中；负责任披露请联系 security@curf.ai）",
