  "releaseLog.v1_2_8.title": "AI 治理修复、移动端导航与 Ask Curf 可读性优化",
  "releaseLog.v1_2_8.c0": "修复了 PII 脱敏未递归处理嵌套对象和数组的问题——REST 数据源会按 API 返回的任意结构返回行数据，而脱敏逻辑此前只检查顶层字符串字段，导致嵌套在对象内部的信用卡号/泰国身份证号/SSN 可能未经遮蔽就进入 LLM 提示词。适用范围不变：仍仅限信用卡号/泰国身份证号/SSN",
  "releaseLog.v1_2_8.c1": "修复了幻觉检测器对 AI 生成百分比数字的误报——数字正则表达式使用的单词边界在 `%` 符号后无法匹配，导致本来正确的百分比数值被标记为无法验证",
  "releaseLog.v1_2_8.c2": "完成了将两条多步骤 Agent 代码路径合并为一套实现（`lib/agent/runLoop.ts`），保留了各自较优的行为，而不是并行运行两套分叉的 Agent 逻辑",
  "releaseLog.v1_2_8.c3": "因果驱动因素分析结果现已接入 Brief 的叙述内容，而不再只是单独展示",
  "releaseLog.v1_2_8.c4": "修复了小屏幕上侧边栏抽屉的问题——此前其高度是按内容而非视口撑开，导致决策之后的导航项（Tables、指标、Agent、Marketplace、Admin 等）无法触及，也无法滚动到",
  "releaseLog.v1_2_8.c5": "修复了 Ask Curf 全工作区回答渲染成一整块难以阅读文字的问题——API 原本已经返回了带编号、分段正确的\"缺失内容\"回答，但回答气泡缺少空白符相关的 CSS，导致所有换行都被折叠",

  "releaseLog.v1_2_6.title": "预测性预警、决策结果追踪、区域渠道与安全加固",
  "releaseLog.v1_2_6.c0": "监控现在可以在阈值被突破之前发出预警，而不仅仅是事后提醒——新增的预测模式会将当前趋势向前推算",
  "releaseLog.v1_2_6.c1": "每个受治理的指标都会自动预测其下一个数值，并自动显示在 Ask Curf、Brief 和指标页面中",
  "releaseLog.v1_2_6.c2": "Brief 现在可以进行前瞻性叙述（例如\"预计将在 Y 之前达到 X\"），而不仅仅是描述已发生的事",
  "releaseLog.v1_2_6.c3": "决策记录会按场景汇总成功率，并在你提交新决策前，展示来自类似历史决策的提示",
  "releaseLog.v1_2_6.c4": "新增 Operate 目标渠道：LINE——可将数据直接推送到 LINE 聊天，与现有的 Slack 和 webhook 渠道并列使用",
  "releaseLog.v1_2_6.c5": "API 密钥现在可以限定作用范围到特定报表，并按密钥计量使用量，使嵌入式分析可以作为独立产品对外销售",
  "releaseLog.v1_2_6.c6": "修复了指标编辑器中存在的跨租户数据泄露风险，并对静态存储的 REST 连接器凭据进行了加密（此前是以明文形式存储）",
  "releaseLog.v1_2_6.c7": "工作区模板现在会遵循套餐对报表和监控的配额限制，而不是绕过这些限制",
  "releaseLog.v1_2_6.c8": "SCIM 目录同步功能现已正确限制为仅 Business 套餐可用",
  "releaseLog.v1_2_6.c9": "将公共 API 的报表运行路径与内部查看器统一——弥补了公共 API 在速率限制和运行历史上的差距，并为内部查看器新增了数据源可见性检查",
  "releaseLog.v1_2_6.c10": "Notebook 的 AI 自动填充功能现已与平台其他部分共用相同的安全控制（Token 预算、使用量追踪、多服务商支持）",
  "releaseLog.v1_2_6.c11": "修复了部分区块类型中图表颜色悄悄偏离当前主题的问题",
  "releaseLog.v1_2_6.c12": "修复了 Story Mode 显示错误货币单位以及\"Why\"按钮无法使用的问题",
  "releaseLog.v1_2_6.c13": "修复了 SQL 防护中的一个漏洞，该漏洞可能让精心构造的查询绕过只读检查夹带写入语句",

  "releaseLog.v1_2_4.title": "语义化指标层、跨工作区 Ask 与决策记录",
  "releaseLog.v1_2_4.c0": "每个业务指标只有一个受治理的定义——Ask、Brief 和监控现在读取同一个数值，而不是各自从自己的报表 SQL 中重新推导",
  "releaseLog.v1_2_4.c1": "Ask Curf 现已覆盖整个工作区——无需先选择报表即可直接提问",
  "releaseLog.v1_2_4.c2": "工作区货币现已可配置（此前所有地方都硬编码为美元）",
  "releaseLog.v1_2_4.c3": "侧边栏中的\"Fast Brief\"已更名为\"Brief\"",
  "releaseLog.v1_2_4.c4": "针对受治理的指标记录一项决策——Curf 会自动重新检查，并告诉你该决策是否按预期推动了数值变化",
  "releaseLog.v1_2_4.c5": "可从指标页面以及 Ask Curf 引用的指标入口进入",
  "releaseLog.v1_2_4.c6": "补齐了\"理解 → 预测 → 行动 → 改进\"闭环——这是第一个用于追踪决策是否真正奏效的功能",

  "releaseLog.v1_2_3.title": "值得信赖的 AI 回答",
  "releaseLog.v1_2_3.c0": "当问题无法用现有数据回答时，Curf 现在会明确说明还需要哪些数据，而不是凭空猜测",

  "releaseLog.v1_2_2.title": "公共 API 与试点上线",
  "releaseLog.v1_2_2.c0": "/api/v1 现已向外部前端开放 dashboards、watchers 和 ask-chat",
  "releaseLog.v1_2_2.c1": "为 /api/v1 添加了 CORS 支持，使外部前端可以调用公共 API",
  "releaseLog.v1_2_2.c2": "为 Zero Dropout 指挥中心试点项目上线了基于角色的登录功能",

  "releaseLog.v1_2_1.title": "工作区与稳定性",
  "releaseLog.v1_2_1.c0": "全新的工作区创建流程",
  "releaseLog.v1_2_1.c1": "改进了 Lake 表的寻址方式",
  "releaseLog.v1_2_1.c2": "侧边栏现已适配小屏幕",
  "releaseLog.v1_2_1.c3": "修复：处于后台浏览器标签页中的 KPI 卡片会显示为 0，而不是真实数值",

