  "forecast.methodology.linear": "该区间为历史数据偏离直线趋势的 ±1.96 倍标准差（约 95% 置信区间），且每个预测周期的宽度保持不变。",
  "forecast.methodology.ets": "该区间为加权拟合误差的 ±1.96 倍标准差，预测周期越往后区间越宽——越远的预测确定性越低。",
  "forecast.methodology.llm": "预测值由模型给出，但置信区间仍沿用直线趋势的误差范围——模型尚未直接生成自己的不确定性估计。",
  "forecast.methodology.why196": "1.96 并非 Curf 专属的数值，而是统计学中 95% 置信区间的标准常数——对于正态分布的数据，95% 的数值会落在均值的 ±1.96 倍标准差范围内。",

